import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { listShippingOptionsForCartWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await listShippingOptionsForCartWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
        option_ids: ["so_123"]
      }
    })

  res.send(result)
}

